import time
import logging

from pyrogram import Client, idle
from pyromod import listen  # type: ignore
from pyrogram.errors import ApiIdInvalid, ApiIdPublishedFlood, AccessTokenInvalid

# FLASK KEEP-ALIVE (for Render deploy workaround)
import os
import logging
from flask import Flask
from threading import Thread

# Reduce noisy access logs (optional, safe)
logging.getLogger("werkzeug").setLevel(logging.ERROR)
flask_app = Flask('')  # same name as original
@flask_app.route("/healthz", methods=["GET", "HEAD"])
def healthz():
    # Ultra-light health endpoint: 204 No Content (0 bytes)
    return ("", 204)
@flask_app.route("/")
def home():
    return "Stats bot is running!"
def run_flask():
    # Render assigns dynamic PORT via env
    port = int(os.getenv("PORT", "8080"))
    flask_app.run(
        host="0.0.0.0",
        port=port,
        debug=False,
        use_reloader=False,
        threaded=True
    )
Thread(target=run_flask, daemon=True).start()

logging.basicConfig(
    level=logging.WARNING, format="%(asctime)s - %(name)s - %(levelname)s - %(message)s"
)

StartTime = time.time()
app = Client(
    "Romeo",
    api_id=API_ID,
    api_hash=API_HASH,
    bot_token=BOT_TOKEN,
    in_memory=True,
    plugins=dict(root="Romeo"),
)

if __name__ == "__main__":
    print("Starting the String Generator Bot...")
    try:
        app.start()
    except (ApiIdInvalid, ApiIdPublishedFlood):
        raise Exception("Your API_ID/API_HASH is not valid.")
    except AccessTokenInvalid:
        raise Exception("Your BOT_TOKEN is not valid.")
    uname = app.get_me().username
    print(f"@{uname} started successfully !")
    idle()
    app.stop()
    print("Bot stopped. Bye !")

